INSERT INTO public."categories" ("id", "description", "name") VALUES
(2, 'Những câu chuyện lãng mạn, sâu lắng về tình yêu và cảm xúc con người', 'Tình cảm'),
(3, 'Nội dung vui nhộn, dí dỏm mang lại tiếng cười và phút giây thư giãn', 'Hài hước'),
(4, 'Tạo cảm giác sợ hãi, rùng rợn và hồi hộp với yếu tố siêu nhiên, kỳ bí', 'Kinh dị'),
(5, 'Thế giới đồ họa sống động, phù hợp mọi lứa tuổi và gia đình', 'Hoạt hình'),
(6, 'Khám phá tương lai, không gian, công nghệ tiên tiến và thế giới tưởng tượng', 'Viễn tưởng'),
(7, 'Những vụ án bí ẩn, đấu trí suy luận logic và vén màn sự thật', 'Trinh thám'),
(8, 'Nhịp phim dồn dập, gây căng thẳng và thắt nút tâm lý nghẹt thở', 'Giật gân'),
(9, 'Tình tiết ly kỳ, bất ngờ và kích thích sự tò mò liên tục của khán giả', 'Hồi Hộp'),
(10, 'Nội dung nhân văn, ấm áp, gắn kết tình cảm giữa các thế hệ', 'Gia đình'),
(11, 'Hành trình khám phá những vùng đất mới lạ, kỳ thú và đầy thử thách', 'Phiêu lưu'),
(12, 'Khai thác chiều sâu tâm lý, cảm xúc và xung đột nội tâm nhân vật', 'Tâm lý'),
(13, 'Tái hiện các sự kiện, bối cảnh và nhân vật lịch sử hào hùng', 'Lịch sử'),
(14, 'Phản ánh sự khốc liệt của chiến trận và phẩm chất kiên cường của con người', 'Chiến tranh'),
(15, 'Thế giới ngầm, các phi vụ phạm tội và cuộc đấu trí với công lý', 'Tội Phạm'),
(16, 'Thế giới phép thuật, thần thoại và những chuyến phiêu lưu kỳ ảo', 'Giả tưởng'),
(1, 'Kịch tính, gay cấn với các cảnh chiến đấu, rượt đuổi và kỹ xảo mãn nhãn', 'Hành động hấp dẫn');
